#!/usr/bin/env python3
"""Fast source-level regression checks for MadNegar 1.0.1.

These checks are deliberately static: they do not replace a Windows/.NET build,
real microphone testing, global-hotkey integration tests, or end-to-end transcription tests.
"""
from pathlib import Path
import re
import sys
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]

def read(name: str) -> str:
    path = ROOT / name
    # Production C# files live under src/; keep their logical names concise in checks.
    if not path.is_file() and path.suffix == ".cs" and len(Path(name).parts) == 1:
        path = ROOT / "src" / name
    return path.read_text(encoding="utf-8")

checks = []
def check(name, condition):
    if not condition:
        raise AssertionError(name)
    checks.append(name)

main = read("MainForm.cs")
settings = read("SettingsForm.cs")
app_settings = read("AppSettings.cs")
hotkey = read("GlobalHotkeySupport.cs")
theme_manager = read("ThemeManager.cs")
audio = read("AudioProcessor.cs")
validation = read("ModelValidation.cs")
zip_extractor = read("SafeZipExtractor.cs")
publish = read("build-release.ps1")
installer = read("Build-Installer.cmd")
release_cmd = read("Build-Release.cmd")
installer_builder = read("Build-Installer.ps1")
installer_iss = read("installer/MadNegar.iss")
readme = read("README.md")
readme_legacy = read("README_FA.md")

project = ET.parse(ROOT / "MadNegar.csproj").getroot()
version = project.findtext("PropertyGroup/Version")
check("project XML parses and version is 1.0.1 release baseline", version == "1.0.1")
source_dir = ROOT / "src"
check("production C# source files are organized under src", source_dir.is_dir() and any(source_dir.glob("*.cs")) and not list(ROOT.glob("*.cs")))
check("main model selector validates Whisper files", "ModelCatalog.Models.Where(m => ModelValidation.IsWhisperModelReady(ModelPath(m)))" in main)
check("settings selector validates Whisper files", "ModelCatalog.Models.Where(m => ModelValidation.IsWhisperModelReady(ModelPath(m)))" in settings)
check("persisted final model is preferred over a stale UI selection", "var savedKey = !string.IsNullOrWhiteSpace(_settings.SelectedModelKey) ? _settings.SelectedModelKey : _settings.SelectedModelId;" in main)
check("missing saved final model does not silently fall back", "A persisted choice must not be silently replaced by a different model." in main)
check("Clear resets live transcript state", "_liveTranscriptText = string.Empty;" in main and "_transcriptBox.Clear();" in main)
check("Clear is disabled while recording/transcribing/busy", "_clearButton.Enabled = _transcriptBox.TextLength > 0 && !_isRecording && !_isStoppingRecording && !_isTranscribing && !_isBusy;" in main)
check("live Auto exposes supported multilingual engines and documents their limits", "if (model.IsWhisper) return !model.EnglishOnly;" in main and "model.IsSupportedForLive && (model.IsFasterWhisper || model.UsesVoskRuntime)" in main and "Whisper.cpp | Final transcription and live preview" in readme and "Vosk | Final transcription and supported live preview" in readme and "Diba-STT | Persian transcription and supported live preview" in readme)
check("live language selection checks provider/model language", "model.Languages.Contains(\"Persian\"" in main and "model.Languages.Contains(\"English\"" in main)
check("settings live picker filters against the saved spoken language", "Where(IsLivePreviewCompatibleForConfiguredLanguage)" in settings and "_settings.SpokenLanguage" in settings)
check("PCM and IEEE-float subtypes are separated", "WaveFormatEncoding.Extensible" in audio and "IeeeFloatSubFormat" in audio and "PcmSubFormat" in audio and "WaveFormatExtraData" in audio)
check("unknown audio formats return a diagnostic path", "Unknown compressed/subtyped formats are not PCM by assumption." in audio and "Unsupported audio format for the level meter" in settings)
check("Whisper validation checks ggml magic and partial download", "WhisperGgmlMagic" in validation and "modelPath + \".partial\"" in validation)
check("faster-whisper validates JSON config and tokenizer/vocabulary", "IsJsonObjectFile(Path.Combine(directory, \"config.json\"))" in validation and "vocabulary.json" in validation)
check("Kaldi/Vosk requires actual model and graph files", '"*.mdl"' in validation and '"*.fst"' in validation)
check("ZIP extraction verifies destination containment", "Path.GetFullPath(Path.Combine(root, normalizedName))" in zip_extractor and "!target.StartsWith(rootPrefix" in zip_extractor)
